:root {
  /* Surface / Elevation */
  --color-bg: #090a0d;
  --color-surface: rgba(255, 255, 255, 0.025);
  --color-surface-raised: rgba(255, 255, 255, 0.04);
  --color-surface-overlay: rgba(18, 19, 26, 0.85);
  --color-surface-sunken: #050507;
  --color-surface-inverse: #f5f5f7;

  /* Text */
  --color-text: #f5f5f7;
  --color-text-secondary: #a1a1aa;
  --color-text-muted: #71717a;
  --color-text-disabled: #52525b;
  --color-text-link: #e2c08d;
  --color-text-inverse: #090a0d;
  --color-text-link-hover: #ebd2aa;
  --color-text-on-accent: #090a0d;

  /* Border / Divider */
  --color-border: rgba(255, 255, 255, 0.08);
  --color-border-subtle: rgba(255, 255, 255, 0.05);
  --color-border-strong: rgba(226, 192, 141, 0.35);
  --color-divider: rgba(255, 255, 255, 0.08);

  /* Accent / Brand */
  --color-accent: #e2c08d;
  --color-accent-hover: #ebd2aa;
  --color-accent-active: #d4ad72;
  --color-accent-subtle: rgba(226, 192, 141, 0.12);
  --color-accent-muted: rgba(226, 192, 141, 0.25);
  --color-accent-border: rgba(226, 192, 141, 0.35);
  --color-accent-text: #e2c08d;
  --color-on-accent: #090a0d;
  --color-accent-secondary: #d4ad72;
  --color-accent-secondary-subtle: rgba(212, 173, 114, 0.1);

  /* Disabled / Inert */
  --color-surface-disabled: rgba(255, 255, 255, 0.02);
  --color-border-disabled: rgba(255, 255, 255, 0.04);
  --color-icon-disabled: #52525b;

  /* Form / Input */
  --color-input-bg: rgba(255, 255, 255, 0.03);
  --color-input-border: rgba(255, 255, 255, 0.1);
  --color-input-border-focus: #e2c08d;
  --color-input-placeholder: #71717a;
  --color-input-bg-hover: rgba(255, 255, 255, 0.05);
  --color-input-bg-disabled: rgba(255, 255, 255, 0.01);
  --color-input-border-hover: rgba(255, 255, 255, 0.2);
  --color-input-border-error: #e5484d;
  --color-input-text: #f5f5f7;
  --color-input-icon: #a1a1aa;

  /* Brand Scale (primitive) */
  --color-brand-50: #fbf7f0;
  --color-brand-100: #f5ede0;
  --color-brand-200: #ead9c2;
  --color-brand-300: #dfc39f;
  --color-brand-400: #e2c08d;
  --color-brand-500: #d4ad72;
  --color-brand-600: #be9557;
  --color-brand-700: #9e7941;
  --color-brand-800: #7d5f34;
  --color-brand-900: #5e4627;

  /* Neutral Scale */
  --color-neutral-50: #f8f9fa;
  --color-neutral-100: #f1f3f5;
  --color-neutral-200: #e9ecef;
  --color-neutral-300: #dee2e6;
  --color-neutral-400: #a1a1aa;
  --color-neutral-500: #71717a;
  --color-neutral-600: #52525b;
  --color-neutral-700: #3f3f46;
  --color-neutral-800: #27272a;
  --color-neutral-900: #18181b;
  --color-neutral-950: #0f1015;
  --color-neutral-1000: #090a0d;

  /* Data Visualization */
  --color-chart-1: #e2c08d;
  --color-chart-2: #70b5f9;
  --color-chart-3: #e5484d;
  --color-chart-4: #46a758;
  --color-chart-5: #f5d90a;
  --color-chart-6: #8e4ec6;
  --color-chart-7: #00c7be;
  --color-chart-8: #f76808;
  --color-chart-grid: rgba(255, 255, 255, 0.05);
  --color-chart-axis: rgba(255, 255, 255, 0.2);
  --color-chart-tooltip-bg: #12131a;

  /* Interaction */
  --color-focus-ring: rgba(226, 192, 141, 0.5);
  --color-hover-overlay: rgba(255, 255, 255, 0.04);
  --color-active-overlay: rgba(255, 255, 255, 0.08);
  --color-selected: rgba(226, 192, 141, 0.15);
  --color-selected-subtle: rgba(226, 192, 141, 0.08);
  --color-pressed-overlay: rgba(0, 0, 0, 0.2);

  /* Semantic State */
  --color-success: #46a758;
  --color-success-subtle: rgba(70, 167, 88, 0.12);
  --color-success-muted: rgba(70, 167, 88, 0.25);
  --color-success-border: rgba(70, 167, 88, 0.35);
  --color-success-text: #63ce70;
  --color-on-success: #090a0d;
  --color-warning: #f5d90a;
  --color-warning-subtle: rgba(245, 217, 10, 0.12);
  --color-warning-muted: rgba(245, 217, 10, 0.25);
  --color-warning-border: rgba(245, 217, 10, 0.35);
  --color-warning-text: #f7ce00;
  --color-on-warning: #090a0d;
  --color-danger: #e5484d;
  --color-danger-subtle: rgba(229, 72, 77, 0.12);
  --color-danger-muted: rgba(229, 72, 77, 0.25);
  --color-danger-border: rgba(229, 72, 77, 0.35);
  --color-danger-text: #ff6369;
  --color-on-danger: #ffffff;
  --color-info: #0091ff;
  --color-info-subtle: rgba(0, 145, 255, 0.12);
  --color-info-muted: rgba(0, 145, 255, 0.25);
  --color-info-border: rgba(0, 145, 255, 0.35);
  --color-info-text: #52a9ff;
  --color-on-info: #ffffff;

  /* Alpha / Overlay */
  --color-scrim: rgba(0, 0, 0, 0.75);
  --color-shadow: rgba(0, 0, 0, 0.8);
  --color-tint-subtle: rgba(226, 192, 141, 0.03);

  /* Font Family */
  --font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-mono: 'JetBrains Mono', monospace;
  --font-display: 'Playfair Display', Georgia, serif;

  /* Display Size */
  --font-size-display-xs: 1.75rem;
  --font-size-display-sm: 2.25rem;
  --font-size-display-md: 3rem;
  --font-size-display-lg: 3.75rem;
  --font-size-display-xl: 4.5rem;

  /* Font Size */
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;
  --font-size-6xl: 3.75rem;
  --font-size-7xl: 4.5rem;

  /* Font Weight */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Line Height */
  --line-height-tight: 1.1;
  --line-height-snug: 1.25;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.7;
  --line-height-none: 1;
  --line-height-loose: 2;

  /* Letter Spacing */
  --letter-spacing-tight: -0.02em;
  --letter-spacing-normal: 0em;
  --letter-spacing-wide: 0.05em;
  --letter-spacing-wider: 0.15em;
  --letter-spacing-tighter: -0.04em;

  /* Text Measure */
  --text-measure-xs: 40ch;
  --text-measure-sm: 50ch;
  --text-measure-md: 60ch;
  --text-measure-lg: 70ch;
  --text-measure-xl: 80ch;
  --text-measure-wide: 90ch;

  /* Spacing */
  --space-0: 0px;
  --space-px: 1px;
  --space-0-5: 0.125rem;
  --space-1: 0.25rem;
  --space-1-5: 0.375rem;
  --space-2: 0.5rem;
  --space-2-5: 0.625rem;
  --space-3: 0.75rem;
  --space-3-5: 0.875rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-7: 1.75rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-14: 3.5rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-28: 7rem;
  --space-32: 8rem;
  --space-40: 10rem;
  --space-48: 12rem;
  --space-56: 14rem;
  --space-64: 16rem;
  --space-72: 18rem;
  --space-80: 20rem;
  --space-96: 24rem;

  /* Section Spacing */
  --section-space-xs: 2.5rem;
  --section-space-sm: 3.5rem;
  --section-space-md: 5rem;
  --section-space-lg: 7rem;
  --section-space-xl: 10rem;
  --section-space-2xl: 14rem;
  --section-space-3xl: 18rem;

  /* Border Radius */
  --radius-none: 0px;
  --radius-xs: 4px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-2xl: 28px;
  --radius-3xl: 36px;
  --radius-full: 9999px;

  /* Border Width */
  --border-width-none: 0px;
  --border-width-thin: 1px;
  --border-width-medium: 2px;
  --border-width-thick: 4px;

  /* Layout / Grid */
  --container-max-width-xs: 480px;
  --container-max-width-sm: 640px;
  --container-max-width-md: 768px;
  --container-max-width-lg: 960px;
  --container-max-width-xl: 1200px;
  --container-max-width-2xl: 1440px;
  --container-padding-sm: 1rem;
  --container-padding-md: 1.5rem;
  --container-padding-lg: 2rem;
  --container-padding-xl: 2.5rem;
  --container-padding-2xl: 3rem;
  --grid-columns: 12;
  --grid-columns-sm: 4;
  --grid-columns-md: 8;
  --grid-columns-lg: 12;
  --grid-columns-xl: 12;
  --grid-gutter: 1.5rem;
  --grid-gutter-sm: 1rem;
  --grid-gutter-md: 1.25rem;
  --grid-gutter-lg: 1.5rem;
  --grid-gutter-xl: 2rem;
  --grid-margin-sm: 1rem;
  --grid-margin-md: 1.5rem;
  --grid-margin-lg: 2rem;
  --grid-margin-xl: 2.5rem;

  /* Composition */
  --composition-max-width: 960px;
  --composition-max-width-wide: 1200px;
  --composition-max-width-narrow: 640px;
  --composition-gutter: 1.5rem;
  --composition-offset-sm: 1rem;
  --composition-offset-md: 2rem;
  --composition-offset-lg: 3rem;
  --composition-overlap-sm: 1.5rem;
  --composition-overlap-md: 3rem;
  --composition-overlap-lg: 4.5rem;
  --composition-aspect-wide: 21 / 9;
  --composition-aspect-standard: 16 / 9;
  --composition-aspect-square: 1 / 1;
  --composition-aspect-portrait: 4 / 5;

  /* Media */
  --media-radius: 16px;
  --media-radius-sm: 10px;
  --media-radius-lg: 20px;
  --media-radius-xl: 28px;
  --media-aspect-wide: 21 / 9;
  --media-aspect-video: 16 / 9;
  --media-aspect-standard: 4 / 3;
  --media-aspect-square: 1 / 1;
  --media-aspect-portrait: 3 / 4;
  --media-overlay: linear-gradient(180deg, rgba(9, 10, 13, 0) 0%, rgba(9, 10, 13, 0.8) 100%);
  --media-overlay-subtle: linear-gradient(180deg, rgba(9, 10, 13, 0) 0%, rgba(9, 10, 13, 0.4) 100%);
  --media-overlay-strong: linear-gradient(180deg, rgba(9, 10, 13, 0.2) 0%, rgba(9, 10, 13, 0.95) 100%);

  /* Sizes */
  --size-icon-xs: 12px;
  --size-icon-sm: 16px;
  --size-icon-md: 20px;
  --size-icon-lg: 24px;
  --size-icon-xl: 32px;
  --size-control-xs: 28px;
  --size-control-sm: 32px;
  --size-control-md: 40px;
  --size-control-lg: 48px;
  --size-control-xl: 56px;
  --size-avatar-xs: 24px;
  --size-avatar-sm: 32px;
  --size-avatar-md: 40px;
  --size-avatar-lg: 48px;
  --size-avatar-xl: 64px;
  --size-header-height: 72px;
  --size-header-height-mobile: 60px;
  --size-sidebar-width: 280px;
  --size-sidebar-width-collapsed: 72px;

  /* Control Geometry */
  --control-padding-x-xs: 0.5rem;
  --control-padding-x-sm: 0.75rem;
  --control-padding-x-md: 1rem;
  --control-padding-x-lg: 1.5rem;
  --control-padding-x-xl: 2rem;
  --control-padding-y-xs: 0.25rem;
  --control-padding-y-sm: 0.375rem;
  --control-padding-y-md: 0.5rem;
  --control-padding-y-lg: 0.75rem;
  --control-padding-y-xl: 1rem;
  --control-radius: 10px;
  --control-border-width: 1px;
  --control-icon-gap: 0.5rem;

  /* Iconography */
  --icon-stroke-width-thin: 1px;
  --icon-stroke-width: 1.5px;
  --icon-stroke-width-medium: 2px;
  --icon-stroke-width-bold: 2.5px;
  --icon-gap-xs: 0.25rem;
  --icon-gap-sm: 0.5rem;
  --icon-gap-md: 0.75rem;

  /* Shadow / Elevation */
  --shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-sm: 0 4px 8px rgba(0, 0, 0, 0.5);
  --shadow-md: 0 12px 24px -4px rgba(0, 0, 0, 0.6);
  --shadow-lg: 0 20px 40px -8px rgba(0, 0, 0, 0.7);
  --shadow-xl: 0 30px 60px -12px rgba(0, 0, 0, 0.85);
  --shadow-2xl: 0 40px 80px -15px rgba(0, 0, 0, 0.95);
  --shadow-inner: inset 0 1px 2px rgba(0, 0, 0, 0.6);
  --shadow-focus: 0 0 0 3px rgba(226, 192, 141, 0.35);
  --shadow-outline: 0 0 0 1px rgba(255, 255, 255, 0.15);

  /* Glow / Light Effects */
  --glow-sm: 0 0 15px rgba(226, 192, 141, 0.15);
  --glow-md: 0 0 30px rgba(226, 192, 141, 0.25);
  --glow-lg: 0 0 50px rgba(226, 192, 141, 0.35);
  --glow-xl: 0 0 80px rgba(226, 192, 141, 0.5);

  /* Blur */
  --blur-sm: 8px;
  --blur-md: 16px;
  --blur-lg: 24px;
  --blur-xl: 40px;

  /* Gradient */
  --gradient-brand: linear-gradient(135deg, #e2c08d 0%, #d4ad72 100%);
  --gradient-brand-subtle: linear-gradient(135deg, rgba(226, 192, 141, 0.15) 0%, rgba(212, 173, 114, 0.05) 100%);
  --gradient-surface: linear-gradient(180deg, rgba(255, 255, 255, 0.03) 0%, rgba(255, 255, 255, 0.005) 100%);
  --gradient-surface-subtle: linear-gradient(180deg, rgba(255, 255, 255, 0.02) 0%, rgba(0, 0, 0, 0.2) 100%);
  --gradient-glow: radial-gradient(1000px circle at 50% -10%, rgba(226, 192, 141, 0.12) 0%, rgba(9, 10, 13, 0) 70%);
  --gradient-fade: linear-gradient(180deg, rgba(9, 10, 13, 0) 0%, #090a0d 100%);
  --gradient-hero: radial-gradient(800px circle at 50% 0%, rgba(226, 192, 141, 0.18) 0%, rgba(9, 10, 13, 0) 100%);

  /* Opacity */
  --opacity-hover: 0.85;
  --opacity-disabled: 0.4;
  --opacity-active: 0.95;
  --opacity-selected: 1;
  --opacity-muted: 0.6;
  --opacity-overlay: 0.8;

  /* Duration */
  --duration-instant: 0ms;
  --duration-fast: 150ms;
  --duration-normal: 250ms;
  --duration-slow: 400ms;
  --duration-slower: 600ms;
  --duration-slowest: 1000ms;

  /* Motion Distance */
  --motion-distance-xs: 2px;
  --motion-distance-sm: 4px;
  --motion-distance-md: 8px;
  --motion-distance-lg: 16px;
  --motion-distance-xl: 32px;

  /* Motion Scale */
  --motion-scale-hover: 1.02;
  --motion-scale-active: 0.98;
  --motion-scale-enter: 0.95;
  --motion-scale-exit: 1.05;

  /* Motion Blur */
  --motion-blur-enter: 8px;
  --motion-blur-exit: 12px;

  /* Easing */
  --ease-linear: linear;
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-smooth: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-emphasized: cubic-bezier(0.2, 0, 0, 1);

  /* Semantic Motion */
  --motion-enter: 400ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-exit: 250ms cubic-bezier(0.4, 0, 1, 1);
  --motion-hover: 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-press: 150ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-reveal: 600ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-layout: 300ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-modal: 400ms cubic-bezier(0.16, 1, 0.3, 1);
  --motion-page: 500ms cubic-bezier(0.16, 1, 0.3, 1);

  /* Z-Index */
  --z-base: 0;
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-overlay: 300;
  --z-modal: 400;
  --z-popover: 500;
  --z-toast: 600;
  --z-tooltip: 700;
  --z-raised: 10;

  /* Breakpoint */
  --breakpoint-xs: 375px;
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  /* Accessibility */
  --focus-ring-width: 2px;
  --focus-ring-offset: 2px;
  --focus-ring-radius: 10px;
  --touch-target-min: 44px;

  /* Component / Button */
  --button-height-sm: 32px;
  --button-height-md: 40px;
  --button-height-lg: 48px;
  --button-height-xl: 56px;
  --button-padding-x-sm: 0.85rem;
  --button-padding-x-md: 1.25rem;
  --button-padding-x-lg: 1.5rem;
  --button-padding-x-xl: 2rem;
  --button-radius: 10px;
  --button-icon-size: 18px;
  --button-gap: 0.5rem;

  /* Component / Card */
  --card-padding-sm: 1.25rem;
  --card-padding-md: 1.75rem;
  --card-padding-lg: 2.5rem;
  --card-padding-xl: 3rem;
  --card-radius: 20px;
  --card-border-width: 1px;
  --card-shadow: 0 30px 60px -12px rgba(0, 0, 0, 0.7);

  /* Component / Navigation */
  --nav-height: 72px;
  --nav-padding-x: 1.5rem;
  --nav-gap: 1rem;
  --nav-item-height: 40px;
  --nav-item-radius: 8px;

  /* Component / Badge */
  --badge-height-sm: 20px;
  --badge-height-md: 26px;
  --badge-padding-x: 0.85rem;
  --badge-radius: 99px;
  --badge-gap: 0.5rem;

  /* Component / Modal */
  --modal-width-sm: 400px;
  --modal-width-md: 560px;
  --modal-width-lg: 720px;
  --modal-width-xl: 960px;
  --modal-padding: 2.5rem;
  --modal-radius: 24px;
  --modal-shadow: 0 40px 80px -15px rgba(0, 0, 0, 0.95);

  /* Component / Tooltip */
  --tooltip-max-width: 280px;
  --tooltip-padding-x: 0.75rem;
  --tooltip-padding-y: 0.375rem;
  --tooltip-radius: 6px;

  /* Component / Input */
  --input-height-sm: 32px;
  --input-height-md: 40px;
  --input-height-lg: 48px;
  --input-padding-x: 1rem;
  --input-padding-y: 0.5rem;
  --input-radius: 10px;
  --input-border-width: 1px;

  /* Component / Avatar */
  --avatar-ring-width: 2px;
  --avatar-ring-color: rgba(226, 192, 141, 0.35);
  --avatar-group-overlap: -8px;

  /* Component / Divider */
  --divider-width: 1px;
  --divider-spacing: 1.5rem;

  /* Component / Overlay */
  --overlay-opacity: 0.75;
  --overlay-blur: 24px;
  --overlay-radius: 20px;

  /* Responsive Layout */
  --mobile-page-padding: 1rem;
  --mobile-section-spacing: 2.5rem;
  --mobile-content-gap: 1rem;
  --mobile-grid-gap: 1rem;
  --desktop-page-padding: 2rem;
  --desktop-section-spacing: 5rem;
  --desktop-content-gap: 1.5rem;
  --desktop-grid-gap: 1.5rem;
}
